{
  "name": "@amykit/plugin-command-gate",
  "version": "0.6.0",
  "description": "A gate that runs the target repository's own commands.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/command-gate"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Use it with ticket-to-qa, which needs a gate port to decide whether a change is ready for review. It runs the target repository's own commands, listed per repository with a default fallback, and refuses a repository that has neither. With file-worktree mounted, the commands run in the work item's own checkout."
  },
  "dependencies": {
    "@amykit/core": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import { CommandRunner, Git, AttemptOutcome, Gate, Workplace } from "@amykit/core";


export interface CommandGateConfig {
  /**
   * The checks to run, per repository, falling back to the `default` entry.
   * Written as shell command lines, because that is how they are written in
   * a repository's own contributor docs.
   */
  commands: Readonly<Record<string, readonly string[]>>;
  timeoutMs?: number;
}

/**
 * The deterministic check, as a list of shell commands run in the work's own
 * tree.
 *
 * It stops at the first failure rather than collecting all of them, so the
 * agent gets one clear thing to fix instead of a wall of noise where the
 * second half is caused by the first.
 */
export class CommandGate implements Gate {
  constructor(
    private readonly runner: CommandRunner,
    private readonly git: Git,
    private readonly config: CommandGateConfig,
  ) {}

  async run(workplace: Workplace): Promise<AttemptOutcome> {
    const commands = this.config.commands[workplace.repo] ?? this.config.commands.default ?? [];
    const at = new Date().toISOString();

    if (commands.length === 0) {
      return {
        ok: false,
        output: `no gate is configured for ${workplace.repo}, so nothing can vouch for this change`,
        at,
      };
    }

    const transcript: string[] = [];

    for (const command of commands) {
      const result = await this.runner.run("sh", ["-c", command], {
        // Where the work is, not where the checkout is: with a worktree port
        // behind the Git, the gate runs in the work's own tree.
        cwd: this.git.pathFor(workplace.repo, workplace.workId),
        timeoutMs: this.config.timeoutMs,
      });

      const output = [result.stdout, result.stderr].filter(Boolean).join("\n").trim();

      if (!result.ok) {
        transcript.push(`$ ${command}\nexited ${result.exitCode}\n\n${output}`);
        return { ok: false, output: transcript.join("\n\n"), at: new Date().toISOString() };
      }

      transcript.push(`$ ${command}\nok`);
    }

    return { ok: true, output: transcript.join("\n"), at: new Date().toISOString() };
  }
}

import { BRANCH_SETTINGS, ConfigSchema } from "@amykit/core";

/**
 * What this plugin needs told to it, and nothing more.
 *
 * The gate is the machine's last word before a pull request, and it was the
 * machine's own top-level key; it moved here. The checkouts and branches the
 * commands run in are the workspace's answer now, so none are named here.
 */
export const configSchema = {
  ...BRANCH_SETTINGS,
  gate: {
    type: "record",
    description: "the deterministic gate commands per repository, with a `default` fallback; a repository with no entry and no `default` is refused rather than waved through",
    default: {},
  },
  timeoutMs: {
    type: "number",
    description: "how long one check may run before it is given up on",
    default: 30 * 60 * 1000,
  },
} satisfies ConfigSchema;

export { CommandGate } from "./CommandGate.js";
export type { CommandGateConfig } from "./CommandGate.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import { definePlugin } from "@amykit/core";
import { CommandGate } from "./CommandGate.js";
import { configSchema } from "./config.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-command-gate",
  configSchema,
  register(registry, ctx) {
    // The gate (and the agent it hands paths to) runs where the work runs:
    // with a worktree port mounted, that is the item's own tree.
    const { git } = ctx.checkouts();

    registry.port(
      "gate",
      new CommandGate(ctx.runner, git, {
        commands: ctx.config.gate as Record<string, string[]>,
        timeoutMs: ctx.config.timeoutMs,
      }),
    );
  },
});
